from lib import *
S = SS('l74')
steps = [
    step("提交数从 1,000 增到 40,000(每个提交只改同一个文件,工作区始终 1 个文件):git status 12 → 12 ms,git log -1 11 → 12 ms,git log --stat -n 100 15 → 15 ms,都不随历史长度变化;git rev-list --count HEAD 14 → 39 → 124 ms,git log --oneline(全部,接 wc)19 → 65 → 213 ms,要走完整个历史的命令随提交数增长。40,000 个提交共 120,000 个对象,.git 目录 11,992 KB。", t=tl(S(1)), mark=lidx(S(1), 'rev-list --count', 'git log --oneline'), done=lidx(S(1), 'git status  ', 'git log -1', 'git log --stat'), b=bars([['git status', 12, '12 ms → 12 ms'], ['git log -1', 12, '11 ms → 12 ms'], ['git log --stat -n 100', 15, '15 ms → 15 ms'], ['rev-list --count', 124, '14 ms → 124 ms'], ['git log --oneline(全部)', 213, '19 ms → 213 ms']], 213, mark=[3, 4], done=[0, 1, 2]), kv=KV([['只看最近的', '耗时不随历史变'], ['走完整个历史', '随提交数增长'], ['status', '与提交数无关']], ['走完整个历史'])),
    step("工作区文件数从 1,000 增到 50,000(1 个提交,全部已跟踪):git status 16 → 30 → 88 ms,git status -uno 16 → 24 → 61 ms,git add -A(没有改动)15 → 29 → 84 ms,git diff --stat HEAD 15 → 24 → 63 ms,git commit --allow-empty 16 → 28 → 74 ms,git ls-files | wc -l 13 → 15 → 20 ms。.git/index 的大小几乎与文件数成正比:50,000 个文件 4,003,071 字节,约每个文件 80 字节。", t=tl(S(2)), mark=lidx(S(2), 'git status  ', 'git add -A', 'git commit --allow-empty'), done=lidx(S(2), 'git ls-files', '50,000 文件:.git/index'), kv=KV([['status / add / commit', '要检查每个文件,随文件数增长'], ['ls-files', '只读 index,增长小'], ['index 大小', '约 80 字节 / 文件']], ['status / add / commit'])),
    step("每个提交新增一个文件(树随提交增长),同一份历史打包存储与松散存储(把 pack 用 git unpack-objects 解开)对比:1,000 提交共 4,000 个对象,打包时 .git 576 KB,松散 16,092 KB;10,000 提交 40,000 个对象,打包 5,260 KB,松散 166,904 KB(4,000 与 40,000 个对象文件)。git rev-list --objects --all:打包 22 / 131 ms,松散 118 / 1368 ms;git cat-file --batch-all-objects:打包 16 / 38 ms,松散 128 / 1325 ms。40,000 提交(160,000 个对象)只测了打包:rev-list --objects --all 948 ms,cat-file 116 ms。", t=tl(S(3)), mark=lidx(S(3), '(松散)', '松散:'), done=lidx(S(3), '(打包)', '打包:', '对象总数'), b=bars([['打包 10,000 提交', 0, '131 ms / 5,260 KB'], ['松散 10,000 提交', 2, '1368 ms / 166,904 KB']], 1, mark=[1], done=[0]), kv=KV([['松散 vs 打包(10,000 提交)', 'rev-list 慢约 10 倍,磁盘约 32 倍'], ['原因', '每个松散对象是一个文件(未单独验证)'], ['40,000 提交', '只测了打包']], ['松散 vs 打包(10,000 提交)'])),
    step("带路径的 git log --oneline -- d07/(结果行数 20 / 200 / 800,三种方式相同)在 1,000 / 10,000 / 40,000 个提交上:没有 commit-graph 18 / 67 / 246 ms;有 commit-graph(不含 Bloom)16 / 37 / 122 ms;commit-graph 加 --changed-paths 16 / 27 / 76 ms。commit-graph 文件在 40,000 提交时 2,620 KB。", t=tl(S(4)), mark=lidx(S(4), '--changed-paths'), done=lidx(S(4), '没有 commit-graph', '无 Bloom', '结果行数'), b=bars([['没有 commit-graph', 2, '246 ms'], ['commit-graph', 1, '122 ms'], ['+ --changed-paths', 0, '76 ms']], 2, mark=[2], done=[0, 1]), kv=KV([['路径过滤', '要比较每个提交的树'], ['commit-graph', '246 → 122 ms'], ['Bloom filter', '→ 76 ms(40,000 提交)']], ['Bloom filter'])),
    step("git clone(file:// 协议,3 次中位数)在 1,000 / 10,000 / 40,000 提交上:完整克隆 143 / 1215 / 6284 ms,.git 600 / 5,412 / 28,224 KB;--depth 1 130 / 858 / 3296 ms,.git 276 / 1,652 / 6,360 KB;--filter=blob:none 181 / 1314 / 7482 ms,.git 692 / 6,228 / 31,272 KB。这组耗时包含检出工作区(最后一个仓库的树里有 40,000 个文件),没有单独拆出。", t=tl(S(5)), mark=lidx(S(5), '--depth 1', '--filter=blob:none'), done=lidx(S(5), '完整克隆'), kv=KV([['完整克隆', '40,000 提交 6.3 s'], ['--depth 1', '3.3 s,.git 只有 6 MB'], ['blob:none', '这里最慢(7.5 s)'], ['注意', '耗时含工作区检出']], ['--depth 1'])),
    step("规模增长 40 倍(提交 1,000 → 40,000)的耗时倍数:status 1.0、log -1 1.1、log --stat -n 100 1.0、rev-list --count 8.8、log --oneline 全部 11.0、log -- 目录 13.8(Bloom 后 4.7)、完整克隆 44.0。文件增长 50 倍(1,000 → 50,000):status 5.6、status -uno 3.7、add -A 5.4、ls-files 1.5。rev-list --objects --all(打包,对象数 ×40)43.5 倍,cat-file --batch-all-objects 7.3 倍。倍数低于规模倍数,是因为每条命令有约 11 ms 的固定启动开销。", t=tl(S(6)), mark=lidx(S(6), 'rev-list --objects', '完整克隆', 'git status  '), done=lidx(S(6), 'git log -1', 'git log --stat', 'ls-files'), kv=KV([['不变', 'status(随提交)、log -1、log -n'], ['随历史', 'rev-list、log、clone'], ['随文件', 'status、add、commit、index']], ['随历史'])),
]
A = mkarti('l74', 74, 'Git,大仓库,性能,status,log,commit-graph,clone,真实验证,动画演示',
    '实测对象数量增长时各命令的耗时:提交数 1,000 → 40,000 时 status 与 log -1 不变、整段历史的遍历随提交数增长;文件数 1,000 → 50,000 时 status、add -A、commit 随文件数增长;松散对象的遍历比打包慢约 10 倍、占盘约 32 倍;带路径的 log 在 commit-graph 与 --changed-paths 下从 246 ms 降到 76 ms;file:// 克隆的耗时与大小。',
    '仓库变大之后,哪些命令会变慢、慢多少、跟什么有关?是提交数、文件数还是对象数?这篇分别把提交数、文件数各放大几十倍,测 status、log、rev-list、add、clone 的耗时,再对比松散与打包存储,以及 commit-graph 与 Bloom filter 的作用。',
    [('12 → 12 ms', '提交数 1,000 → 40,000 时 git status 的耗时:status 看的是工作区,与历史长度无关'), ('16 → 88 ms', '工作区文件数 1,000 → 50,000 时 git status 的耗时'), ('246 → 76 ms', '40,000 提交上 git log -- 目录:没有 commit-graph 与加上 --changed-paths 的对比')],
    [('随提交数:只看最近的与走完整段历史', '<p>提交数增长 40 倍,<code>git status</code>、<code>git log -1</code>、<code>git log --stat -n 100</code> 的耗时没有变化;<code>rev-list --count</code> 与完整的 <code>git log --oneline</code> 要遍历所有提交,耗时随提交数增长。</p>'),
     ('随文件数', '<p>文件数增长 50 倍,<code>status</code>、<code>add -A</code>、<code>commit</code> 的耗时增长 4 到 6 倍(都要检查每个已跟踪文件),<code>ls-files</code> 只读 index,增长很小。index 文件约每个文件 80 字节。</p>'),
     ('松散对象与打包对象', '<p>同一份历史,10,000 个提交的松散存储遍历全部对象比打包慢约 10 倍,磁盘占用约 32 倍(166,904 KB 对 5,260 KB)。40,000 个提交的松散存储没有测。</p>'),
     ('带路径的 log', '<p><code>git log -- 目录</code> 要比较每个提交的树。commit-graph 把 246 ms 降到 122 ms,再加 <code>--changed-paths</code> 的 Bloom filter 降到 76 ms(40,000 提交)。</p>'),
     ('克隆', '<p><code>file://</code> 克隆的耗时随提交数增长;<code>--depth 1</code> 在这里也要 3.3 s,因为最新提交的树里有 40,000 个文件;<code>--filter=blob:none</code> 在这个带检出的场景里最慢。耗时里包含检出,没有拆开。</p>'),
     ('倍数与固定开销', '<p>每条命令都有约 11 ms 的启动开销,所以小规模时倍数偏低。表里的“随历史”“随文件”“不变”三类划分来自上面的测量。</p>')],
    steps,
    [ENV_I_GIT + '。历史由 git fast-import 一次造出;每个数字是 5 次(最大规模 3 次)的中位数;每个命令都经过 shell 调用,包含进程启动;克隆用 file:// 加 --no-local;未启用 fsmonitor、untracked cache',
     '没有验证:真正的大仓库(百万级提交、数十万以上文件);网络克隆的耗时;松散对象慢的具体原因(只测了耗时与文件数);40,000 提交的松散存储;克隆耗时里检出与传输各占多少;稀疏检出、部分克隆下的 status;Linux 上的文件系统差异;冷缓存(重启后第一次)的耗时;这些数字在其它机器上的绝对值'],
    '大仓库的耗时')
